//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils_detect.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stockSearch.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
scwin.vScrenID = "ULDSTF35402.xml";
scwin.MSG_CHK_NEW = "데이터를 추가하려면 신규버튼을 누른 후 입력하세요.";
scwin.TR_JOB;
scwin.rowPos;
scwin.parentWin;
scwin.pIndex;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetHeader = function() {
    dts_Item.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=CORRCT_FACTR_INOUT";
    dts_Item.reset();
    dts_Item.insertRow();
};
scwin.fn_initItem = function() {
    dts_Item.Reset();
    dts_Item.insertRow();
};
scwin.fn_OpenDetail = function(row) {
    dts_Item.setCellData(1, "ISU_CD", dts_List.getCellData(dts_List.getRowPosition(), "ISU_CD"));
    dts_Item.setCellData(1, "ISUR_CD", dts_List.getCellData(dts_List.getRowPosition(), "ISUR_CD"));
    dts_Item.setCellData(1, "COM_NM", dts_List.getCellData(dts_List.getRowPosition(), "COM_NM"));
    dts_Item.setCellData(1, "CORRCT_FACTR", dts_List.getCellData(dts_List.getRowPosition(), "CORRCT_FACTR"));
    dts_Item.setCellData(1, "ADJ_DD", dts_List.getCellData(dts_List.getRowPosition(), "ADJ_DD"));
    buttonSet.setUpdateStatus();
};
scwin.fn_list_sync = function() {
    // 조회
    var url = "/AdminAndDlstedDetection.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listCorrctFactr&outputMessageId=CORRCT_FACTR_INOUT&JOB_TYPE=" + scwin.pIndex;
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
};
scwin.fn_save = function() {
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목]을 선택하세요.");
        return;
    }
    scwin.TR_JOB = 'I';
    scwin.fn_trs(TR_JOB_INSERT);
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    scwin.rowPos = dts_List.getRowPosition();
    scwin.fn_trs(TR_JOB_UPDATE);
};
scwin.fn_delete = function() {
    scwin.TR_JOB = 'D';
    scwin.fn_trs(TR_JOB_DELETE);
};
scwin.fn_trs = function(gJobType) {
    if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
    dts_Item.setCellData(1, "JOB_TYPE", gJobType);
    var vScrenProcTpCd;
    if (scwin.TR_JOB == "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB == "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB == "D") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    trs.Action = $c.lc.fn_encodeNSession("/AdminAndDlstedDetection.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=saveCorrctFactr");
    trs.KeyName = "toinb_dataid4";
    trs.KeyValue = "JSP(I:pInput=dts_Item)";
    trs.Post();
};
scwin.img_ISU_NM_onclick = function() {
    if (dts_Item.getTotalRow() == 0) {
        $c.win.alert(scwin.MSG_CHK_NEW);
        return;
    }
    $c.stockSearch.JongmokSearch(txb_ISU_CD, txb_ISU_NM, SECUGRP_ID_ST, '2', 'A');
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_New_onclick = function() {
    buttonSet.setInsertStatus();
    scwin.fn_initItem();
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    //alert(dts_List.NameValue(dts_List.RowPosition, "CORRCT_FACTR"));
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
};
scwin.trs_OnFail = function() {
    $c.stf.alert_error(dts_Item);
};
scwin.trs_OnSuccess = function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_list_sync();
    scwin.fn_initItem();
    //alert('[TR_JOB]'+TR_JOB);
    if (scwin.TR_JOB == 'U') {
        dts_List.setRowPosition(scwin.rowPos, 0);
        scwin.fn_OpenDetail(scwin.rowPos);
    } else {
        dts_List.setRowPosition(dts_List.getTotalRow(), 0);
        scwin.fn_OpenDetail(dts_List.getTotalRow());
    }
};
scwin.grd_List_OnClick = function(row, colid) {
    scwin.fn_OpenDetail(row);
};
scwin.edt_CORRCT_FACTR_OnKeyDown = function(keycode, skeycode) {
    // JACKAL_19.09.27

    //if (dts_List.countRow == 0) {

    //	alert(MSG_CHK_NEW);

    //	edt_CORRCT_FACTR.text = "";

    //}

};
scwin.gform_onload = function() {
    scwin.parentWin = $c.frame.path("../");
    scwin.pIndex = scwin.parentWin.MaxTab_01.getSelectedTabIndex();
    $c.libRoundPanel.PanelToGroupBox(panel_Item);
    scwin.fn_list_sync();

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제

    scwin.fn_SetHeader();
    buttonSet.setInsertStatus();
};
